Module PECFILLTBS.
Import PMS.
Abbreviation CAD := PeCLayoutS.CADDR_S.

Ltac tr64 M0 AG := lazymatch goal with |- L5.u64_at ?sg ?M2 ?a ?v =>
  let X := fresh "X" in assert (X : L5.u64_at sg M0 a v) by PMK.gmem;
  apply (L5C.u64_at_agree sg M0 M2 a v); [apply AG; lia | lia | lia | exact X] end.

Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PECKS.klayout_S L LY.
Let SF := PECKS.sfoot_S L LY.

(* [comment removed for export] *)
Definition ctbfill_res (pl : list Z) (R R' : bvmap 5 word) (M' : word -> option byte) (src src' : PM.srcst) (sm sm' : PM.strm) : Prop :=
  src' = src /\ exists p c, getr R 11%bv = Z_to_bv 64 p /\ getr R' 10%bv = Z_to_bv 64 c /\ 0 <= c <= PM.CHUNK /\ PM.sm_g sm' = PM.sm_g sm + c
    /\ (c < PM.CHUNK -> PM.sm_g sm' = PM.sm_eg sm /\ PM.sm_st sm' = 2) /\ (PM.sm_st sm = 2 -> c = 0)
    /\ L5.defined M' p c /\ L5.bytes_at RSEGS M' p (UbjRef.slice pl (blen pl - (PM.sm_eg sm - PM.sm_g sm)) c)
    /\ (PM.sm_st sm' = 2 -> PM.sm_g sm' = PM.sm_eg sm').
Definition cfill_tb_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (cr : credit) (sp r fb : Z) (pl : list Z) (s : PM.pst) (str : PM.vstr) (sm : PM.strm) (Wextra : list L5.range),
    hi_heap HI (PM.parser_own s ++ LBX) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] -> PMSP.entry CAD L R M sp r 3 -> PMSP.frame_ok CAD L sp fb ->
    getr R 10%bv = Z_to_bv 64 (PMSP.o_src CAD fb) ->
    (exists p, getr R 11%bv = Z_to_bv 64 p /\ getr R 12%bv = Z_to_bv 64 PM.CHUNK /\ exists c n q, PM.p_tb s = PM.VLong c n q /\ q <= p /\ p + PM.CHUNK <= q + c) ->
    (exists p, getr R 11%bv = Z_to_bv 64 p /\ 0 <= p < 2 ^ 64 /\ Wextra = [(p, PM.CHUNK)]) ->
    PM.parser_at RSEGS CAD PMSP.T3 PMSP.T4 M (PMSP.o_p CAD fb) (PMSP.o_is CAD fb) s -> PM.iss_at RSEGS CAD PMSP.T3 M (PMSP.o_is CAD fb) str sm ->
    PMST.base_ok RSEGS CAD M -> incl (PM.vs_own str) LBX ->
    PECS.payload_ok pl -> PEC.content_ok RSEGS CAD M fb pl (PM.p_src s) str sm ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (src' : PM.srcst) (sm' : PM.strm),
        regs_preserved R R' ->
        PM.parser_at RSEGS CAD PMSP.T3 PMSP.T4 M' (PMSP.o_p CAD fb) (PMSP.o_is CAD fb)
          (PM.PST (PM.p_more s) (PM.p_done s) (PM.p_depth s) src' (PM.p_tb s) (PM.p_tg s) (PM.p_b s) (PM.p_k s) (PM.p_stk s)) ->
        PM.iss_at RSEGS CAD PMSP.T3 M' (PMSP.o_is CAD fb) str sm' -> PMSP.src_step (PM.p_src s) src' sm sm' ->
        ctbfill_res pl R R' M' (PM.p_src s) src' sm sm' ->
        L5C.hpres L (PM.parser_own s ++ LBX) sp (PMSP.pm_scr 3) (PMSP.W_src CAD fb (PM.p_src s) ++ Wextra) M M' ->
        hi_heap HI (PM.parser_own s ++ LBX) cr M' (m_vmmaps model) ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R (pa_fill_buffer CAD) M model) K.

Theorem cfill_tb_ok : cfill_tb_spec.
